const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length);
const n = parseInt(tok[0]), q = parseInt(tok[1]);
const LOG = 60;
const first = new Int32Array(n + 1);
for (let v = 1; v <= n; v++) first[v] = parseInt(tok[1 + v]);
const up = [first];
for (let j = 1; j < LOG; j++) {
  const prev = up[j - 1], cur = new Int32Array(n + 1);
  for (let v = 1; v <= n; v++) cur[v] = prev[prev[v]];
  up.push(cur);
}
const out = [];
let pos = 2 + n;
for (let i = 0; i < q; i++) {
  let v = parseInt(tok[pos]);
  let k = BigInt(tok[pos + 1]);              // k reaches 10^18, beyond exact Number range
  pos += 2;
  let j = 0;
  while (k > 0n) {
    if (k & 1n) v = up[j][v];
    k >>= 1n;
    j++;
  }
  out.push(v);
}
console.log(out.join('\n'));

