#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, q;
    scanf("%d %d", &n, &q);
    const int LOG = 60;
    vector<vector<int>> up(LOG, vector<int>(n + 1, 0));
    for (int v = 1; v <= n; v++) scanf("%d", &up[0][v]);
    for (int j = 1; j < LOG; j++)
        for (int v = 1; v <= n; v++) up[j][v] = up[j - 1][up[j - 1][v]];
    while (q--) {
        int v;
        long long k;
        scanf("%d %lld", &v, &k);
        for (int j = 0; k > 0; j++, k >>= 1)
            if (k & 1) v = up[j][v];
        printf("%d\n", v);
    }
    return 0;
}
